import com.sedsoftware.sproutpace.data.ADVERTISING_PRIVACY_ENDPOINT
import com.sedsoftware.sproutpace.data.ADVERTISING_PRIVACY_PAYLOAD_VERSION
import com.sedsoftware.sproutpace.data.AdvertisingPrivacyState
import com.sedsoftware.sproutpace.data.ConsentChoice
import com.sedsoftware.sproutpace.data.ProductSettings
import kotlinx.coroutines.sync.Mutex
import kotlinx.coroutines.sync.withLock

enum class ConsentDecision { ACCEPTED, DECLINED, WITHDRAWN }

interface PrivatePrivacyStore {
    fun readState(): AdvertisingPrivacyState?
    fun writeState(value: AdvertisingPrivacyState)
    fun clearState()
}

/** The only production persistence adapter for region metadata and the policy-bound user choice. */
class ProductSettingsPrivacyStore(private val settings: ProductSettings) : PrivatePrivacyStore {
    override fun readState(): AdvertisingPrivacyState? = settings.privacyState.value
    override fun writeState(value: AdvertisingPrivacyState) = settings.setPrivacyState(value)
    override fun clearState() = settings.setPrivacyState(null)
}

class PrivacyRepository(
    private val store: PrivatePrivacyStore,
) {
    fun read(nowEpochMillis: Long): AdvertisingPrivacyState? = runCatching { store.readState() }
        .getOrNull()?.takeIf { it.isFreshAndValid(nowEpochMillis) }

    fun readForRefresh(nowEpochMillis: Long): AdvertisingPrivacyState? = runCatching { store.readState() }
        .getOrNull()?.takeIf { it.isContractValid(nowEpochMillis) }

    fun write(region: PrivacyRegion, decision: ConsentDecision?) {
        store.writeState(
            AdvertisingPrivacyState(
                payloadVersion = ADVERTISING_PRIVACY_PAYLOAD_VERSION,
                endpoint = ADVERTISING_PRIVACY_ENDPOINT,
                schemaVersion = region.schemaVersion,
                consentRequired = region.consentRequired,
                policyVersion = region.policyVersion,
                fetchedAtEpochMillis = region.fetchedAtEpochMillis,
                expiresAtEpochMillis = region.expiresAtEpochMillis,
                choice = decision?.takeIf { region.consentRequired }?.toStoredChoice() ?: ConsentChoice.UNDECIDED,
            ),
        )
    }

    fun clear() = store.clearState()

    companion object {
        fun isFresh(state: AdvertisingPrivacyState, now: Long): Boolean = state.isFreshAndValid(now)

        private fun AdvertisingPrivacyState.isFreshAndValid(now: Long): Boolean {
            if (!isContractValid(now)) return false
            return expiresAtEpochMillis > now
        }

        private fun AdvertisingPrivacyState.isContractValid(now: Long): Boolean {
            val lifetime = expiresAtEpochMillis - fetchedAtEpochMillis
            return payloadVersion == ADVERTISING_PRIVACY_PAYLOAD_VERSION &&
                endpoint == PRIVACY_REGION_ENDPOINT &&
                schemaVersion == PRIVACY_REGION_SCHEMA_VERSION &&
                POLICY_VERSION.matches(policyVersion) &&
                fetchedAtEpochMillis in 0..now &&
                lifetime in 1..PRIVACY_CACHE_MAX_AGE_MILLIS
        }

        private val POLICY_VERSION = Regex("[A-Za-z0-9][A-Za-z0-9._-]{0,127}")
    }
}

sealed interface PrivacyEligibility {
    data class Eligible(val sdkConsent: Boolean, val policyVersion: String) : PrivacyEligibility
    data class ConsentRequired(val policyVersion: String) : PrivacyEligibility
    data class Disabled(val reason: DisabledReason) : PrivacyEligibility
}

enum class DisabledReason {
    REGION_UNAVAILABLE,
    CONSENT_DECLINED,
    CONSENT_WITHDRAWN,
    PLATFORM_DISABLED,
    HOST_DISABLED,
    MISSING_AD_UNIT,
    PROHIBITED_PLACEMENT,
    SDK_FAILURE,
}

class PrivacyCoordinator(
    private val api: PrivacyRegionApi,
    private val repository: PrivacyRepository,
    private val clock: EpochMillisClock,
) {
    private val mutex = Mutex()

    suspend fun resolve(): PrivacyEligibility = mutex.withLock {
        runCatching { resolveLocked() }.getOrElse {
            PrivacyEligibility.Disabled(DisabledReason.REGION_UNAVAILABLE)
        }
    }

    private suspend fun resolveLocked(): PrivacyEligibility {
        val now = clock.now()
        val payload = repository.read(now) ?: refresh(now) ?: return PrivacyEligibility.Disabled(
            DisabledReason.REGION_UNAVAILABLE,
        )
        return payload.toEligibility()
    }

    fun recordDecision(decision: ConsentDecision): Boolean = runCatching {
        val now = clock.now()
        val payload = repository.read(now) ?: return@runCatching false
        if (!payload.consentRequired) return@runCatching false
        repository.write(
            payload.toRegion(),
            decision,
        )
        true
    }.getOrDefault(false)

    fun withdraw(): Boolean = recordDecision(ConsentDecision.WITHDRAWN)

    private suspend fun refresh(now: Long): AdvertisingPrivacyState? {
        val previous = repository.readForRefresh(now)
        val region = api.fetch().getOrElse {
            return null
        }
        val preservedConsent = previous?.choice?.toDecision()?.takeIf {
            region.consentRequired && previous.policyVersion == region.policyVersion
        }
        repository.write(region, preservedConsent)
        return repository.read(now)
    }

    private fun AdvertisingPrivacyState.toEligibility(): PrivacyEligibility {
        if (!consentRequired) {
            return PrivacyEligibility.Eligible(sdkConsent = false, policyVersion = policyVersion)
        }
        return when (choice.toDecision()) {
            ConsentDecision.ACCEPTED -> PrivacyEligibility.Eligible(true, policyVersion)
            ConsentDecision.DECLINED -> PrivacyEligibility.Disabled(DisabledReason.CONSENT_DECLINED)
            ConsentDecision.WITHDRAWN -> PrivacyEligibility.Disabled(DisabledReason.CONSENT_WITHDRAWN)
            null -> PrivacyEligibility.ConsentRequired(policyVersion)
        }
    }

    private fun AdvertisingPrivacyState.toRegion() = PrivacyRegion(
        schemaVersion,
        consentRequired,
        policyVersion,
        fetchedAtEpochMillis,
        expiresAtEpochMillis,
    )
}

private fun ConsentDecision.toStoredChoice(): ConsentChoice = when (this) {
    ConsentDecision.ACCEPTED -> ConsentChoice.ACCEPTED
    ConsentDecision.DECLINED -> ConsentChoice.DECLINED
    ConsentDecision.WITHDRAWN -> ConsentChoice.WITHDRAWN
}

private fun ConsentChoice.toDecision(): ConsentDecision? = when (this) {
    ConsentChoice.UNDECIDED -> null
    ConsentChoice.ACCEPTED -> ConsentDecision.ACCEPTED
    ConsentChoice.DECLINED -> ConsentDecision.DECLINED
    ConsentChoice.WITHDRAWN -> ConsentDecision.WITHDRAWN
}
package com.sedsoftware.sproutpace.monetization

import com.sedsoftware.sproutpace.data.AdvertisingPrivacyState
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.sync.Mutex
import kotlinx.coroutines.sync.withLock

enum class AdSurface { CATALOG, HISTORY, OTHER }
enum class AdHostMode { PRODUCTION, DEBUG, PREVIEW, AUTOMATED_TEST }
enum class AdPlatform { ANDROID, IOS }

data class AdConfiguration(
    val platform: AdPlatform,
    val hostMode: AdHostMode,
    val productionAdUnitId: String?,
) {
    val effectiveAdUnitId: String?
        get() = when (hostMode) {
            AdHostMode.DEBUG -> ANDROID_DEMO_BANNER_ID.takeIf { platform == AdPlatform.ANDROID }
            AdHostMode.PRODUCTION -> productionAdUnitId?.trim()?.takeIf(::isProductionAdUnitId)
            AdHostMode.PREVIEW, AdHostMode.AUTOMATED_TEST -> null
        }

    companion object {
        const val ANDROID_DEMO_BANNER_ID = "demo-banner-yandex"
        private val PRODUCTION_ID = Regex("R-M-[0-9]+-[0-9]+")
        fun isProductionAdUnitId(value: String): Boolean = PRODUCTION_ID.matches(value) &&
            value != ANDROID_DEMO_BANNER_ID
    }
}

data class AdPlacementRequest(
    val surface: AdSurface,
    val realItemCount: Int,
    val offline: Boolean,
    val slotIndex: Int,
)

object InlineAdPlacementPolicy {
    const val CATALOG_INSERTION_INDEX = 4
    const val HISTORY_INSERTION_INDEX = 5

    fun permits(request: AdPlacementRequest): Boolean {
        if (request.offline) return false
        val expectedIndex = when (request.surface) {
            AdSurface.CATALOG -> CATALOG_INSERTION_INDEX
            AdSurface.HISTORY -> HISTORY_INSERTION_INDEX
            AdSurface.OTHER -> return false
        }
        return request.slotIndex == expectedIndex && request.realItemCount > expectedIndex
    }
}

interface AdSdkDriver {
    val platform: AdPlatform
    val supported: Boolean
    suspend fun setUserConsent(consent: Boolean)
    suspend fun initialize()
    suspend fun stopNewRequestsAndDispose()
}

sealed interface AdPreparation {
    data class Ready(val adUnitId: String) : AdPreparation
    data class ConsentRequired(val policyVersion: String) : AdPreparation
    data class Disabled(val reason: DisabledReason) : AdPreparation
}

/** Narrow production boundary consumed by the UI; platform SDK types never cross common code. */
interface AdvertisingRuntime {
    val privacyState: StateFlow<AdvertisingPrivacyState?>
    suspend fun prepare(request: AdPlacementRequest): AdPreparation
    suspend fun acceptConsent(): Boolean
    suspend fun declineConsent(): Boolean
    suspend fun withdrawConsent(): Boolean
    fun close()
}

class AdvertisingController(
    private val privacy: PrivacyCoordinator,
    private val sdk: AdSdkDriver,
    private val configuration: AdConfiguration,
) {
    private val mutex = Mutex()
    private var initialized = false
    private var activeSdkConsent: Boolean? = null

    suspend fun prepare(request: AdPlacementRequest): AdPreparation = mutex.withLock {
        if (!sdk.supported || configuration.platform != AdPlatform.ANDROID) {
            return@withLock AdPreparation.Disabled(DisabledReason.PLATFORM_DISABLED)
        }
        if (configuration.hostMode == AdHostMode.PREVIEW || configuration.hostMode == AdHostMode.AUTOMATED_TEST) {
            return@withLock AdPreparation.Disabled(DisabledReason.HOST_DISABLED)
        }
        val adUnitId = configuration.effectiveAdUnitId
            ?: return@withLock AdPreparation.Disabled(DisabledReason.MISSING_AD_UNIT)
        if (!InlineAdPlacementPolicy.permits(request)) {
            return@withLock AdPreparation.Disabled(DisabledReason.PROHIBITED_PLACEMENT)
        }
        when (val eligibility = privacy.resolve()) {
            is PrivacyEligibility.ConsentRequired -> AdPreparation.ConsentRequired(eligibility.policyVersion)
            is PrivacyEligibility.Disabled -> AdPreparation.Disabled(eligibility.reason)
            is PrivacyEligibility.Eligible -> runCatching {
                if (!initialized) {
                    sdk.setUserConsent(eligibility.sdkConsent)
                    sdk.initialize()
                    initialized = true
                    activeSdkConsent = eligibility.sdkConsent
                } else if (activeSdkConsent != eligibility.sdkConsent) {
                    sdk.setUserConsent(eligibility.sdkConsent)
                    activeSdkConsent = eligibility.sdkConsent
                }
                AdPreparation.Ready(adUnitId)
            }.getOrElse {
                AdPreparation.Disabled(DisabledReason.SDK_FAILURE)
            }
        }
    }

    suspend fun acceptConsent(): Boolean = mutex.withLock {
        privacy.recordDecision(ConsentDecision.ACCEPTED)
    }

    suspend fun declineConsent(): Boolean = mutex.withLock {
        val recorded = privacy.recordDecision(ConsentDecision.DECLINED)
        stopImmediately()
        recorded
    }

    suspend fun withdrawConsent(): Boolean = mutex.withLock {
        val recorded = privacy.withdraw()
        stopImmediately()
        recorded
    }

    private suspend fun stopImmediately() {
        runCatching { sdk.setUserConsent(false) }
        activeSdkConsent = false
        runCatching { sdk.stopNewRequestsAndDispose() }
    }
}

enum class InlineAdState { IDLE, LOADING, LOADED, FAILED, DISPOSED }

class InlineAdSession(private val maxRetries: Int = 1) {
    var state: InlineAdState = InlineAdState.IDLE
        private set
    private var failures = 0

    fun beginLoad(): Boolean {
        if (state == InlineAdState.DISPOSED || state == InlineAdState.LOADING || state == InlineAdState.LOADED) return false
        if (failures > maxRetries) return false
        state = InlineAdState.LOADING
        return true
    }

    fun loaded() {
        if (state == InlineAdState.LOADING) state = InlineAdState.LOADED
    }

    fun failed() {

        database.saveBatch(batch)

        database.deleteBatch(batch.id)

        assertTrue(database.snapshot().batches.isEmpty())
        assertTrue(database.snapshot().observations.isEmpty())
    }

