    zones.isEmpty() || trays.isEmpty() -> WorkspaceSetupState.NOT_CONFIGURED
    plans.isEmpty() -> WorkspaceSetupState.NO_PLAN
    batches.isEmpty() -> WorkspaceSetupState.NO_BATCHES
